lines = text.strip().split("\n")

def parse(vs):
    m = re.match(r'([\d.]+)\s*\((\d+)\)', vs.strip())
    if not m: return None, None
    v = float(m.group(1))
    u = int(m.group(2))
    d = len(m.group(1).split('.')[1]) if '.' in m.group(1) else 0
    return v, u / (10**d)

fwhm = lambda e: 0.8 + 0.001 * e

# Use 615.520 as reference to calibrate N_counts
ref = [l for l in lines if '615.520' in l][0]
_, ref_e_str = ref.split('|')
ref_i, ref_iu = parse(ref_e_str)
# The dE for 615.520
ref_de = 0.027
ref_n = (fwhm(615.520) / ref_de)**2
n_ref = ref_n / ref_i

print(f"Reference: 615.520 keV, I={ref_i}, dE={ref_de}")
print(f"FWHM(615)={fwhm(615.520):.2f} keV")
print(f"N_ref(344 keV ref) ~ {n_ref:.0f} counts")
print()

results = []
for line in lines:
    parts = line.split('|')
    e_val, e_unc = parse(parts[0])
    i_val, i_unc = parse(parts[1])
    n = i_val * n_ref
    de_exp = fwhm(e_val) / math.sqrt(n)
    ratio = e_unc / de_exp
    sigma_i = i_val / i_unc if i_unc else 999
    results.append((e_val, e_unc, i_val, i_unc, de_exp, ratio, n, sigma_i))

# Sort by how unexpectedly precise (ratio < 1 = more precise than statistics allow)
results.sort(key=lambda x: x[5])

print(f"{'E_gamma':>9}  {'dE_obs':>7}  {'dE_exp':>7}  {'obs/exp':>7}  {'I_gamma':>9}  {'I/dI':>6}  {'Comment'}")
print("=" * 72)
for e, de_o, i_val, i_unc, de_e, ratio, n, si in results:
    c = ""
    if ratio < 0.2:
        c = "<<< IMPOSSIBLE: dE {:.0f}x smaller than statistics".format(1/ratio)
    elif ratio < 0.35:
        c = "<<< SUSPICIOUS: dE {:.0f}x smaller than statistics".format(1/ratio)
    elif ratio < 0.5:
        c = "<<< OPTIMISTIC: dE {:.0f}x smaller than statistics".format(1/ratio)
    print(f"{e:>9.3f}  {de_o:>7.4f}  {de_e:>7.4f}  {ratio:>7.2f}  {i_val:>9.5f}  {si:>6.1f}  {c}")
